import React from 'react';
import Error404Icon from './components/Error404Icon/Error404Icon';
import { Container, Description, ErrorImage } from '../Error.styles';
import { Heading, Paragraph } from '../../typography';
import { Button } from '../../button';

export interface Props {
  buttonClickHandler: () => void;
  headerText: string;
  subHeaderText: string;
  buttonText: string;
}

const Error404 = ({
  buttonClickHandler,
  buttonText,
  headerText,
  subHeaderText,
}: Props): JSX.Element => (
  <Container data-testid="error404">
    <ErrorImage error="404">
      <Error404Icon />
    </ErrorImage>
    <Heading size="H2">{headerText}</Heading>
    <Description>
      <Paragraph size="basis">{subHeaderText}</Paragraph>
    </Description>
    <Button onClick={buttonClickHandler} data-testid="error404-button" size="large">
      {buttonText}
    </Button>
  </Container>
);

export default Error404;
